// Approved reference data that ships with the app (generated by scripts/build-reference-store.js from bundles that
// were reviewed and whose content fingerprints were checked at build time). Read-only; nothing here touches the
// network, a database or a model.

import { REFERENCE_STORE_SOURCES, REFERENCE_STORE_PASSAGES } from './referenceStore.data.js'

const sourceById = new Map(REFERENCE_STORE_SOURCES.map(s => [s.id, s]))
const byKey = new Map()
for (const p of REFERENCE_STORE_PASSAGES) {
  const k = `${p.branch}|${p.personnel_category}|${p.occupation_code}`
  if (!byKey.has(k)) byKey.set(k, [])
  byKey.get(k).push(p)
}

// Tests exercise the Supabase registry path against synthetic data; they switch the shipped data off so it cannot
// answer in its place. Production never calls this.
let enabled = true
export function useBundledReference(on) { enabled = !!on }

export function bundledPassages(branch, category, code) {
  return enabled ? byKey.get(`${branch}|${category}|${code}`) || [] : []
}

export function bundledSource(id) {
  return enabled ? sourceById.get(id) || null : null
}

export function bundledCodes(branch, category) {
  const prefix = `${branch}|${category}|`
  return [...byKey.keys()].filter(k => k.startsWith(prefix)).map(k => k.slice(prefix.length))
}
